text:
{
  "fill": [
    {
      "prompt": "解法是讓伺服器在回應裡加上 ___，說明哪些 ___ 可以讀這個回應。",
      "answers": [
        [
          "標頭",
          "header"
        ],
        [
          "來源"
        ]
      ]
    },
    {
      "prompt": "瀏覽器看到標頭符合才把結果交給網頁，否則即使 ___ 成功也 ___ 內容。",
      "answers": [
        [
          "請求",
          "請求動作"
        ],
        [
          "讀不到"
        ]
      ]
    },
    {
      "prompt": "如果請求需要帶上憑證，伺服器必須明確指名允許的來源，不能使用 ___。",
      "answers": [
        [
          "萬用字元",
          "wildcard"
        ]
      ]
    }
  ],
  "apply": [
    {
      "prompt": "某網站的前端和 API 位於不同網域，請求雖然成功，但前端讀不到回應內容。請說明伺服器需要怎麼做，以及為什麼前端不能自行解決這個問題。",
      "rubric": [
        "是否指出伺服器需要在回應中加入說明允許來源的標頭",
        "是否指出瀏覽器只有在標頭符合時才會把結果交給網頁",
        "是否指出決定跨來源讀取權限的是伺服器而不是發請求的網頁"
      ]
    },
    {
      "prompt": "某跨來源請求需要帶上憑證，伺服器想用最寬鬆的設定允許所有來源。請判斷這樣是否符合規則，並提出應採取的設定方向。",
      "rubric": [
        "是否指出帶憑證的請求不能使用萬用字元",
        "是否指出伺服器必須明確指名允許的來源"
      ]
    }
  ]
}
